∀ {E : Type u_1}
  [inst : NormedAddCommGroup E] [inst_1 : InnerProductSpace ℝ E] [inst_2 : FiniteDimensional ℝ E]
  [inst_3 : MeasurableSpace E] [BorelSpace E] (μ : MeasureTheory.Measure E) [MeasureTheory.IsProbabilityMeasure μ]
  {η : ℝ},
  0 < η →
    let J :=
      MeasureTheory.Measure.map (fun (p : E × E) => (p.1, p.1 + √η • p.2)) (μ.prod (ProbabilityTheory.stdGaussian E));
    have F := fun (p : E × E) => (p.1, 2 • p.1 - p.2);
    have P :=
      (MeasureTheory.lpMeas ℝ ℝ (MeasurableSpace.comap Prod.snd inferInstance) 2 J).subtypeL ∘SL
        MeasureTheory.condExpL2 ℝ ℝ (Measurable.comap_le measurable_snd);
    ∃ (R : ProbabilityTheory.Kernel E E),
      ProbabilityTheory.IsMarkovKernel R ∧
        (∀ (y : E), R y = μ.tilted fun (x : E) => -‖x - y‖ ^ 2 / (2 * η)) ∧
          ∃ (U : ↥(MeasureTheory.Lp ℝ 2 J) →ₗᵢ[ℝ] ↥(MeasureTheory.Lp ℝ 2 J)),
            (∀ (f : ↥(MeasureTheory.Lp ℝ 2 J)), ↑↑(U f) =ᵐ[J] ↑↑f ∘ F) ∧
              Function.Involutive ⇑U ∧
                IsSelfAdjoint U.toContinuousLinearMap ∧
                  (∀ (f : ↥(MeasureTheory.Lp ℝ 2 J)), ↑↑(P f) =ᵐ[J] fun (p : E × E) => ∫ (x : E), ↑↑f (x, p.2) ∂R p.2) ∧
                    have A := P * U.toContinuousLinearMap * P;
                    have B := (1 - P) * U.toContinuousLinearMap * P;
                    have D := (1 - P) * U.toContinuousLinearMap * (1 - P);
                    star B * B = P - A ^ 2 ∧
                      star B * D = -(A * star B) ∧
                        ∀ (f : ↥(MeasureTheory.Lp ℝ 2 J)), P f = f → ‖B f‖ ^ 2 = ‖f‖ ^ 2 - ‖A f‖ ^ 2
